  avgLoad: number;
  overloaded: Array<{
    agentId: string;
    agentType: string;
    utilization: number;
    excessClaims: number;
    movableClaims: ClaimSummary[];
  }>;
  underloaded: Array<{
    agentId: string;
    agentType: string;
    utilization: number;
    availableCapacity: number;
  }>;
  recommendations: string[];
}

