/**
 * Vector Clock for federated claim aggregates.
 *
 * Replaces the per-aggregate integer `version` counter in
 * `InMemoryClaimEventStore` with a per-aggregate vector clock that captures
 * causal history across nodes. Two events with concurrent vector clocks
 * (neither is happens-before the other) signal a true concurrent-write
 * conflict that the application layer must resolve via the existing contest
 * mechanism.
 *
 * @module v3/claims/infrastructure/vector-clock
 * @see ADR-101 Component B
 */

/**
 * A vector clock — `{[nodeId]: integer}` representing the causal history
 * seen at the issuing node when an event was created.
 */
export interface VectorClock {
  readonly clocks: Readonly<Record<string, number>>;
}

/**
 * The all-zero vector clock. Used as the seed for new aggregates.
 */
export function zeroVectorClock(): VectorClock {
  return Object.freeze({ clocks: Object.freeze({}) });
}

/**
 * Increment the entry for `nodeId` in `vc` by 1.
 * Used when a node generates a new local event.
 *
 * Pure function — does not mutate `vc`.
 */
export function tickVectorClock(vc: VectorClock, nodeId: string): VectorClock {
  if (!nodeId) {
    throw new Error('tickVectorClock: nodeId must be non-empty');
  }
  const current = vc.clocks[nodeId] ?? 0;
  return Object.freeze({
    clocks: Object.freeze({ ...vc.clocks, [nodeId]: current + 1 }),
  });
}

/**
 * Merge two vector clocks by taking the per-node maximum.
 * Used when a node receives a remote event — the merged clock represents
 * "everything I know about, plus everything the remote knows about."
 *
 * Pure function — returns a new VectorClock.
 */
export function mergeVectorClocks(a: VectorClock, b: VectorClock): VectorClock {
  const merged: Record<string, number> = { ...a.clocks };
  for (const [nodeId, value] of Object.entries(b.clocks)) {
    const current = merged[nodeId] ?? 0;
    if (value > current) {
      merged[nodeId] = value;
    }
  }
  return Object.freeze({ clocks: Object.freeze(merged) });
}

/**
 * Result of comparing two vector clocks. Unlike scalar clocks, vector
 * clocks form a partial order — two clocks can be EQUAL, BEFORE, AFTER,
 * or CONCURRENT (genuinely incomparable).
 */
export type VectorClockOrder = 'equal' | 'before' | 'after' | 'concurrent';

/**
 * Compare two vector clocks. Returns:
 *   - 'equal'      : a and b are identical
 *   - 'before'     : a happens-before b (a ⊑ b strict)
 *   - 'after'      : b happens-before a
 *   - 'concurrent' : neither dominates — true concurrent writes
 *
 * Reference: Lamport 1978, "Time, Clocks, and the Ordering of Events".
 */
export function compareVectorClocks(a: VectorClock, b: VectorClock): VectorClockOrder {
  // Collect every nodeId that appears in either clock; missing entries are 0.
  const allNodes = new Set<string>([
    ...Object.keys(a.clocks),
    ...Object.keys(b.clocks),
  ]);

  let aDominates = false; // ∃ node where a > b
  let bDominates = false; // ∃ node where b > a

  for (const nodeId of allNodes) {
    const av = a.clocks[nodeId] ?? 0;
    const bv = b.clocks[nodeId] ?? 0;
    if (av > bv) aDominates = true;
    if (bv > av) bDominates = true;
  }

  if (!aDominates && !bDominates) return 'equal';
  if (aDominates && !bDominates) return 'after';
  if (!aDominates && bDominates) return 'before';
  return 'concurrent';
}

/**
 * `true` iff a and b are concurrent (neither happens-before the other).
 * The contest mechanism in `WorkStealingService` is invoked exactly when
 * this returns `true` for two writes against the same claim aggregate.
 */
export function areConcurrent(a: VectorClock, b: VectorClock): boolean {
  return compareVectorClocks(a, b) === 'concurrent';
}

/**
 * Serialize a vector clock to a stable string representation, suitable for
 * use as an idempotency key or log line. Sorted by nodeId for determinism.
 */
export function vectorClockToString(vc: VectorClock): string {
  const entries = Object.entries(vc.clocks).sort(([a], [b]) => a.localeCompare(b));
  return entries.map(([k, v]) => `${k}:${v}`).join(',') || '∅';
}

/**
 * Prune entries for nodes no longer in the federation.
 * Used during peer-eviction (per ADR-097) to keep clocks bounded.
 *
 * @param vc      Vector clock to prune
 * @param keepers Set of nodeIds that should remain
 */
export function pruneVectorClock(vc: VectorClock, keepers: ReadonlySet<string>): VectorClock {
  const pruned: Record<string, number> = {};
  for (const [nodeId, value] of Object.entries(vc.clocks)) {
    if (keepers.has(nodeId)) {
      pruned[nodeId] = value;
    }
  }
  return Object.freeze({ clocks: Object.freeze(pruned) });
}

/**
 * V3 Claude-Flow Claim Service Unit Tests
 *
 * London School TDD - Behavior Verification
 * Tests issue/task claiming, releasing, handoffs, and status transitions
 *
 * @module v3/claims/tests/claim-service
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { createMock, type MockedInterface } from '../../testing/src/helpers/create-mock.js';

// =============================================================================
// Domain Types
// =============================================================================

type ClaimantType = 'agent' | 'human';
type ClaimStatus = 'active' | 'pending_handoff' | 'expired' | 'released';
type HandoffDirection = 'human_to_agent' | 'agent_to_agent' | 'agent_to_human';

interface Claimant {
  type: ClaimantType;
  id: string;
  agentType?: string;
  humanId?: string;
}

interface Claim {
  issueId: string;
  claimant: Claimant;
  status: ClaimStatus;
  claimedAt: Date;
  expiresAt: Date;
  metadata: ClaimMetadata;
}

interface ClaimMetadata {
  reason?: string;
  priority?: number;
  handoffRequested?: boolean;
  handoffTarget?: Claimant;
  handoffReason?: string;
}

interface HandoffRequest {
  claimId: string;
  from: Claimant;
  to: Claimant;
  reason: string;
  requestedAt: Date;
}

// =============================================================================
// Event Types
// =============================================================================

interface ClaimEvent {
  type: string;
  timestamp: Date;
  payload: unknown;
}

type ClaimEventType =
  | 'IssueClaimed'
  | 'IssueReleased'
  | 'HandoffRequested'
  | 'HandoffAccepted'
  | 'HandoffRejected'
  | 'ClaimStatusUpdated'
  | 'ClaimExpired';

// =============================================================================
// Interfaces (Collaborators)
// =============================================================================

interface IClaimRepository {
  findById(issueId: string): Promise<Claim | null>;
  save(claim: Claim): Promise<Claim>;
  update(claim: Claim): Promise<Claim>;
  delete(issueId: string): Promise<void>;
  findByClaimant(claimantId: string): Promise<Claim[]>;
  findExpiredClaims(before: Date): Promise<Claim[]>;
  findPendingHandoffs(): Promise<Claim[]>;
}

interface IEventStore {
  append(event: ClaimEvent): Promise<void>;
  getEvents(issueId: string): Promise<ClaimEvent[]>;
}

interface IClaimValidator {
  validateClaim(issueId: string, claimant: Claimant): Promise<{ valid: boolean; error?: string }>;
  validateHandoff(from: Claimant, to: Claimant): Promise<{ valid: boolean; error?: string }>;
}

interface IExpirationPolicy {
  calculateExpiration(claimant: Claimant): Date;
  isExpired(claim: Claim): boolean;
}

// =============================================================================
// Service Under Test
// =============================================================================

interface ClaimResult {
  success: boolean;
  claim?: Claim;
  error?: string;
}

interface ReleaseResult {
  success: boolean;
  error?: string;
}

interface HandoffResult {
  success: boolean;
  handoffRequest?: HandoffRequest;
  error?: string;
}

interface StatusUpdateResult {
  success: boolean;
  previousStatus?: ClaimStatus;
  newStatus?: ClaimStatus;
  error?: string;
}

interface ExpireResult {
  expiredCount: number;
  claims: Claim[];
}

class ClaimService {
  constructor(
    private readonly repository: IClaimRepository,
    private readonly eventStore: IEventStore,
    private readonly validator: IClaimValidator,
    private readonly expirationPolicy: IExpirationPolicy
  ) {}

  async claim(issueId: string, claimant: Claimant): Promise<ClaimResult> {
    // Check if already claimed
    const existing = await this.repository.findById(issueId);
    if (existing && existing.status === 'active') {
      throw new Error('Issue already claimed');
    }

    // Validate claim
    const validation = await this.validator.validateClaim(issueId, claimant);
    if (!validation.valid) {
      return { success: false, error: validation.error };
    }

    // Create claim
    const claim: Claim = {
      issueId,
      claimant,
      status: 'active',
      claimedAt: new Date(),
      expiresAt: this.expirationPolicy.calculateExpiration(claimant),
      metadata: {},
    };

    const savedClaim = await this.repository.save(claim);

    // Emit event
    await this.eventStore.append({
      type: 'IssueClaimed',
      timestamp: new Date(),
      payload: { issueId, claimant },
    });

    return { success: true, claim: savedClaim };
  }

  async release(issueId: string, claimant: Claimant): Promise<ReleaseResult> {
    const existing = await this.repository.findById(issueId);
    if (!existing) {
      return { success: false, error: 'Claim not found' };
    }

    // Verify ownership
    if (existing.claimant.id !== claimant.id) {
      throw new Error('Not the owner of this claim');
    }

    // Update status and save
    existing.status = 'released';
    await this.repository.update(existing);

    // Emit event
    await this.eventStore.append({
      type: 'IssueReleased',
      timestamp: new Date(),
      payload: { issueId, releasedBy: claimant },
    });

    return { success: true };
  }

  async requestHandoff(
    issueId: string,
    from: Claimant,
    to: Claimant,
    reason: string
  ): Promise<HandoffResult> {
    const existing = await this.repository.findById(issueId);
    if (!existing) {
      return { success: false, error: 'Claim not found' };
    }

    // Verify ownership
    if (existing.claimant.id !== from.id) {
      return { success: false, error: 'Not the owner of this claim' };
    }

    // Validate handoff
    const validation = await this.validator.validateHandoff(from, to);
    if (!validation.valid) {
      return { success: false, error: validation.error };
    }

    // Update claim with handoff request
    existing.status = 'pending_handoff';
    existing.metadata.handoffRequested = true;
    existing.metadata.handoffTarget = to;
    existing.metadata.handoffReason = reason;
    await this.repository.update(existing);

    const handoffRequest: HandoffRequest = {
      claimId: issueId,
      from,
      to,
      reason,
      requestedAt: new Date(),
    };

    // Emit event
    await this.eventStore.append({
      type: 'HandoffRequested',
      timestamp: new Date(),
      payload: handoffRequest,
    });

    return { success: true, handoffRequest };
  }

  async acceptHandoff(issueId: string, acceptingClaimant: Claimant): Promise<HandoffResult> {
    const existing = await this.repository.findById(issueId);
    if (!existing) {
      return { success: false, error: 'Claim not found' };
    }

    if (existing.status !== 'pending_handoff') {
      return { success: false, error: 'No pending handoff for this claim' };
    }

    // Verify the accepting claimant is the target
    if (existing.metadata.handoffTarget?.id !== acceptingClaimant.id) {
      return { success: false, error: 'Not the handoff target' };
    }

    // Transfer ownership
    const previousOwner = existing.claimant;
    existing.claimant = acceptingClaimant;
    existing.status = 'active';
    existing.claimedAt = new Date();
    existing.expiresAt = this.expirationPolicy.calculateExpiration(acceptingClaimant);
    existing.metadata.handoffRequested = false;
    existing.metadata.handoffTarget = undefined;
    existing.metadata.handoffReason = undefined;

    await this.repository.update(existing);

    // Emit event
    await this.eventStore.append({
      type: 'HandoffAccepted',
      timestamp: new Date(),
      payload: { issueId, from: previousOwner, to: acceptingClaimant },
    });

    return { success: true };
  }

  async rejectHandoff(issueId: string, rejectingClaimant: Claimant, reason: string): Promise<HandoffResult> {
    const existing = await this.repository.findById(issueId);
    if (!existing) {
      return { success: false, error: 'Claim not found' };
    }

    if (existing.status !== 'pending_handoff') {
      return { success: false, error: 'No pending handoff for this claim' };
    }

    // Verify the rejecting claimant is the target
    if (existing.metadata.handoffTarget?.id !== rejectingClaimant.id) {
      return { success: false, error: 'Not the handoff target' };
    }

    // Restore to active status
    existing.status = 'active';
    existing.metadata.handoffRequested = false;
    existing.metadata.handoffTarget = undefined;
    existing.metadata.handoffReason = undefined;

    await this.repository.update(existing);

    // Emit event
    await this.eventStore.append({
      type: 'HandoffRejected',
      timestamp: new Date(),
      payload: { issueId, rejectedBy: rejectingClaimant, reason },
    });

    return { success: true };
  }

  async updateStatus(issueId: string, newStatus: ClaimStatus, claimant: Claimant): Promise<StatusUpdateResult> {
    const existing = await this.repository.findById(issueId);
    if (!existing) {
      return { success: false, error: 'Claim not found' };
    }

    // Verify ownership for status changes
    if (existing.claimant.id !== claimant.id) {
      return { success: false, error: 'Not the owner of this claim' };
    }

    // Validate status transition
    const validTransitions: Record<ClaimStatus, ClaimStatus[]> = {
      active: ['pending_handoff', 'released', 'expired'],
      pending_handoff: ['active', 'released'],
      expired: ['active'], // Can reactivate expired claims
      released: [], // Terminal state
    };

    if (!validTransitions[existing.status].includes(newStatus)) {
      return {
        success: false,
        error: `Invalid status transition from ${existing.status} to ${newStatus}`,
      };
    }

    const previousStatus = existing.status;
    existing.status = newStatus;
    await this.repository.update(existing);

    // Emit event
    await this.eventStore.append({
      type: 'ClaimStatusUpdated',
      timestamp: new Date(),
      payload: { issueId, previousStatus, newStatus },
    });

    return { success: true, previousStatus, newStatus };
  }

  async expireStale(cutoffDate: Date): Promise<ExpireResult> {
    const expiredClaims = await this.repository.findExpiredClaims(cutoffDate);
    const processedClaims: Claim[] = [];

    for (const claim of expiredClaims) {
      if (this.expirationPolicy.isExpired(claim)) {
        claim.status = 'expired';
        await this.repository.update(claim);
        processedClaims.push(claim);

        // Emit event for each expired claim
        await this.eventStore.append({
          type: 'ClaimExpired',
          timestamp: new Date(),
          payload: { issueId: claim.issueId, expiredAt: cutoffDate },
        });
      }
    }

    return {
      expiredCount: processedClaims.length,
      claims: processedClaims,
    };
  }
}

