  const humanClaimant: Claimant = {
    type: 'human',
    id: 'user-123',
    humanId: 'john.doe',
  };

  const anotherAgentClaimant: Claimant = {
    type: 'agent',
    id: 'reviewer-1',
    agentType: 'reviewer',
  };

