// =============================================================================
// Integration tests for event subscribers
// =============================================================================

describe('Event Subscription', () => {
  let mockEventPublisher: MockedInterface<IEventPublisher>;
  let subscribedHandlers: Map<ClaimEventType, EventHandler[]>;

  beforeEach(() => {
    subscribedHandlers = new Map();
    mockEventPublisher = createMock<IEventPublisher>();

    mockEventPublisher.subscribe.mockImplementation((type, handler) => {
      const handlers = subscribedHandlers.get(type) || [];
      handlers.push(handler);
      subscribedHandlers.set(type, handlers);
    });

    mockEventPublisher.unsubscribe.mockImplementation((type, handler) => {
      const handlers = subscribedHandlers.get(type) || [];
      const index = handlers.indexOf(handler);
      if (index > -1) {
        handlers.splice(index, 1);
      }
      subscribedHandlers.set(type, handlers);
    });
  });

  it('should allow subscribing to specific event types', () => {
    // Given
    const handler: EventHandler = vi.fn();

    // When
    mockEventPublisher.subscribe('IssueClaimed', handler);

    // Then
    expect(subscribedHandlers.get('IssueClaimed')).toContain(handler);
  });

  it('should allow unsubscribing from events', () => {
    // Given
    const handler: EventHandler = vi.fn();
    mockEventPublisher.subscribe('IssueClaimed', handler);

    // When
    mockEventPublisher.unsubscribe('IssueClaimed', handler);

    // Then
    expect(subscribedHandlers.get('IssueClaimed')).not.toContain(handler);
  });

  it('should support multiple handlers for same event type', () => {
    // Given
    const handler1: EventHandler = vi.fn();
    const handler2: EventHandler = vi.fn();

    // When
    mockEventPublisher.subscribe('IssueClaimed', handler1);
    mockEventPublisher.subscribe('IssueClaimed', handler2);

    // Then
    const handlers = subscribedHandlers.get('IssueClaimed');
    expect(handlers).toContain(handler1);
    expect(handlers).toContain(handler2);
    expect(handlers?.length).toBe(2);
  });

  it('should allow same handler for different event types', () => {
    // Given
    const sharedHandler: EventHandler = vi.fn();

    // When
    mockEventPublisher.subscribe('IssueClaimed', sharedHandler);
    mockEventPublisher.subscribe('IssueReleased', sharedHandler);

    // Then
    expect(subscribedHandlers.get('IssueClaimed')).toContain(sharedHandler);
    expect(subscribedHandlers.get('IssueReleased')).toContain(sharedHandler);
  });
});

/**
 * Federated event store tests.
 *
 * Coverage targets (per ADR-101 Component B):
 *   - vector-clock advances on each local append
 *   - remote events that strictly precede local state are no-ops
 *   - remote events concurrent with local state throw ConcurrentWriteError
 *   - PII detected during publish rolls back the local append
 *   - HLC merges from remote events
 *   - subscribe / getEvents / getEventsByType / getEventsByIssueId pass through
 */

import { describe, expect, it, beforeEach, vi } from 'vitest';
import { InMemoryClaimEventStore } from '../src/infrastructure/event-store';
import {
  FederatedClaimEventStore,
  ConcurrentWriteError,
} from '../src/infrastructure/federated-event-store';
import {
  FederationBridge,
  type IFederationTransport,
  PiiLeakPreventedError,
} from '../src/infrastructure/federation-bridge';
import { LocalHlc } from '../src/infrastructure/hlc';
import {
  zeroVectorClock,
  tickVectorClock,
  type VectorClock,
} from '../src/infrastructure/vector-clock';
import type { ClaimDomainEvent } from '../src/domain/events';

// ───── helpers ─────

function makeEvent(overrides: Partial<ClaimDomainEvent> = {}): ClaimDomainEvent {
  return {
    id: `evt-${Math.random().toString(36).slice(2, 10)}`,
    type: 'claim:created',
    aggregateId: 'claim-001',
    aggregateType: 'claim',
    version: 0,
    timestamp: Date.now(),
    source: 'test',
    payload: { foo: 'bar' },
    ...overrides,
  };
}

function makeStore(opts: {
  nodeId?: string;
  bridge?: FederationBridge;
} = {}) {
  const local = new InMemoryClaimEventStore();
  const hlc = new LocalHlc(opts.nodeId ?? 'node-A', () => 1_000_000);
  const store = new FederatedClaimEventStore({
    local,
    hlc,
    nodeId: opts.nodeId ?? 'node-A',
    bridge: opts.bridge,
  });
  return { local, hlc, store };
}

// ───── tests ─────

describe('FederatedClaimEventStore', () => {
  describe('local append', () => {
    it('ticks the per-aggregate vclock on each local append', async () => {
      const { store } = makeStore();
      await store.initialize();

      await store.append(makeEvent({ id: 'e1' }));
      const vc1 = store.getAggregateVclock('claim-001');
      expect(vc1.clocks).toEqual({ 'node-A': 1 });

      await store.append(makeEvent({ id: 'e2' }));
      const vc2 = store.getAggregateVclock('claim-001');
      expect(vc2.clocks).toEqual({ 'node-A': 2 });
    });

    it('keeps separate vclocks per aggregate', async () => {
      const { store } = makeStore();
      await store.initialize();

      await store.append(makeEvent({ aggregateId: 'claim-001' }));
      await store.append(makeEvent({ aggregateId: 'claim-002' }));

      expect(store.getAggregateVclock('claim-001').clocks).toEqual({ 'node-A': 1 });
      expect(store.getAggregateVclock('claim-002').clocks).toEqual({ 'node-A': 1 });
    });
  });

  describe('applyRemoteEvent', () => {
    it('accepts a remote event that strictly follows local state', async () => {
      const { store } = makeStore();
      await store.initialize();

      // Remote knows about node-A's first event AND has added its own.
      const remoteVclock: VectorClock = Object.freeze({
        clocks: Object.freeze({ 'node-B': 1 }),
      });

      await store.applyRemoteEvent(
        makeEvent({ id: 'e-remote' }),
        remoteVclock,
        { physicalMs: 1_000_000, logical: 0, nodeId: 'node-B' },
      );

      expect(store.getAggregateVclock('claim-001').clocks).toEqual({ 'node-B': 1 });
    });

    it('drops remote events that are equal to or before local state (idempotent)', async () => {
      const { store } = makeStore();
      await store.initialize();

      await store.append(makeEvent({ id: 'e1' })); // local at {A:1}
      const beforeCount = (await store.getEvents('claim-001')).length;

      // Remote tries to deliver an event with clock {A:1} — already known.
      await store.applyRemoteEvent(
        makeEvent({ id: 'e-rebroadcast' }),
        Object.freeze({ clocks: Object.freeze({ 'node-A': 1 }) }),
        { physicalMs: 1_000_000, logical: 0, nodeId: 'node-A' },
      );

      const afterCount = (await store.getEvents('claim-001')).length;
      expect(afterCount).toBe(beforeCount); // no duplicate
    });

    it('throws ConcurrentWriteError on concurrent vclocks', async () => {
      const { store } = makeStore();
      await store.initialize();

      // Local has {A:1}; remote has {B:1} — concurrent.
      await store.append(makeEvent({ id: 'e-local' }));

      await expect(
        store.applyRemoteEvent(
          makeEvent({ id: 'e-remote' }),
          Object.freeze({ clocks: Object.freeze({ 'node-B': 1 }) }),
          { physicalMs: 1_000_000, logical: 0, nodeId: 'node-B' },
        ),
      ).rejects.toBeInstanceOf(ConcurrentWriteError);
    });
  });

  describe('PII rollback', () => {
    it('rolls back the local append when the bridge throws PiiLeakPrevented', async () => {
      // Mock transport: scanPii throws, publish never called.
      const transport: IFederationTransport = {
        publish: vi.fn(),
        scanPii: vi.fn(async () => {
          throw new PiiLeakPreventedError('payload', 'looks like an SSN');
        }),
      };
      const bridge = new FederationBridge({ nodeId: 'node-A', transport });
      const { store, local } = makeStore({ bridge });
      await store.initialize();

      const event = makeEvent({ id: 'e-pii' });
      await expect(store.append(event)).rejects.toBeInstanceOf(PiiLeakPreventedError);

      // Local store should NOT contain the event.
      const events = await local.getEvents('claim-001');
      expect(events.find((e) => e.id === 'e-pii')).toBeUndefined();

      // Aggregate vclock should NOT have advanced past zero (or whatever it was before).
      const vc = store.getAggregateVclock('claim-001');
      expect(vc.clocks).toEqual({});

      // Transport publish should not have been called.
      expect(transport.publish).not.toHaveBeenCalled();
    });

    it('keeps the local append when the bridge succeeds', async () => {
      const published: any[] = [];
      const transport: IFederationTransport = {
        publish: vi.fn(async (env) => { published.push(env); }),
        scanPii: vi.fn(async () => { /* clean */ }),
      };
      const bridge = new FederationBridge({ nodeId: 'node-A', transport });
      const { store, local } = makeStore({ bridge });
      await store.initialize();

      await store.append(makeEvent({ id: 'e-clean' }));

      expect((await local.getEvents('claim-001')).length).toBe(1);
      expect(published.length).toBe(1);
      expect(published[0].type).toBe('claim-event');
      expect(published[0].payload.event.id).toBe('e-clean');
    });
  });

  describe('wouldConflict', () => {
    it('returns true for concurrent clocks, false otherwise', async () => {
      const { store } = makeStore();
      await store.initialize();

      await store.append(makeEvent());

      // Same node-A vclock — not concurrent (equal/before)
      expect(
        store.wouldConflict('claim-001', tickVectorClock(zeroVectorClock(), 'node-A')),
      ).toBe(false);

      // node-B with no awareness of node-A — concurrent
      expect(
        store.wouldConflict('claim-001', tickVectorClock(zeroVectorClock(), 'node-B')),
      ).toBe(true);
    });
  });

  describe('IClaimEventStore pass-through', () => {
    it('getEvents / getEventsByType / getEventsByIssueId delegate to local', async () => {
      const { store } = makeStore();
      await store.initialize();

      await store.append(makeEvent({ id: 'e1', aggregateId: 'claim-001' }));
      await store.append(makeEvent({
        id: 'e2',
        aggregateId: 'claim-002',
        type: 'claim:released',
        payload: { issueId: 'issue-XYZ' },
      }));

      expect((await store.getEvents('claim-001')).length).toBe(1);
      expect((await store.getEventsByType('claim:released')).length).toBe(1);
      expect((await store.getEventsByIssueId('issue-XYZ')).length).toBe(1);
    });

    it('subscribe returns an unsubscribe function', async () => {
      const { store } = makeStore();
      await store.initialize();

      const handler = vi.fn();
      const unsub = store.subscribe(['claim:created'], handler);
      expect(typeof unsub).toBe('function');

      await store.append(makeEvent({ type: 'claim:created' }));
      // Subscriptions are async — give the microtask queue a chance.
      await Promise.resolve();
      expect(handler).toHaveBeenCalled();

      unsub();
      handler.mockClear();
      await store.append(makeEvent({ type: 'claim:created' }));
      await Promise.resolve();
      expect(handler).not.toHaveBeenCalled();
    });
  });
});

/**
 * Hybrid Logical Clock tests.
 *
 * Coverage targets (per ADR-101 Component A):
 *   - monotonic advance under wall-clock advance
 *   - logical bumps when wall clock stalls
 *   - logical bumps when wall clock goes backward
 *   - update() merges remote causality correctly
 *   - skew guard rejects far-future remote HLCs
 *   - compare yields a total order across nodes
 *   - degeneracy: single-node HLCs are wall-clock-equivalent
 */

import { describe, expect, it } from 'vitest';
import {
  LocalHlc,
  HlcSkewError,
  compareHlc,
  zeroHlc,
  hlcToWallMs,
  wallMsToHlc,
  DEFAULT_MAX_SKEW_MS,
  type HlcTimestamp,
} from '../src/infrastructure/hlc';

/** Build a controllable physical-clock function for tests. */
function fakeClock(start: number) {
  let t = start;
  return {
    advance(ms: number) { t += ms; },
    setTo(ms: number) { t = ms; },
    read: () => t,
  };
}

describe('LocalHlc', () => {
  it('refuses an empty nodeId', () => {
    expect(() => new LocalHlc('')).toThrow(/non-empty nodeId/);
  });

  describe('now()', () => {
    it('advances physicalMs when wall clock advances', () => {
      const wall = fakeClock(1_000);
      const hlc = new LocalHlc('node-A', wall.read);
      const t0 = hlc.now();
      wall.advance(500);
      const t1 = hlc.now();
      expect(t1.physicalMs).toBe(1_500);
      expect(t1.logical).toBe(0);
      expect(compareHlc(t0, t1)).toBe(-1);
    });

    it('bumps logical when wall clock has not advanced', () => {
      const wall = fakeClock(1_000);
      const hlc = new LocalHlc('node-A', wall.read);
      const t0 = hlc.now();
      const t1 = hlc.now();
      const t2 = hlc.now();
      // wall clock didn't move — logical should monotonically increase
      expect(t1.physicalMs).toBe(t0.physicalMs);
      expect(t1.logical).toBe(t0.logical + 1);
      expect(t2.logical).toBe(t1.logical + 1);
      expect(compareHlc(t0, t1)).toBe(-1);
      expect(compareHlc(t1, t2)).toBe(-1);
    });

    it('bumps logical when wall clock goes backward', () => {
      const wall = fakeClock(2_000);
      const hlc = new LocalHlc('node-A', wall.read);
      const t0 = hlc.now();
      wall.setTo(1_000); // NTP correction, VM resume, etc.
      const t1 = hlc.now();
      // physical does NOT regress; logical bumps to keep monotonicity
      expect(t1.physicalMs).toBe(t0.physicalMs);
      expect(t1.logical).toBeGreaterThan(t0.logical);
      expect(compareHlc(t0, t1)).toBe(-1);
    });
  });

  describe('update()', () => {
    it('takes the max physical and bumps logical when remote is concurrent', () => {
      const wall = fakeClock(1_000);
      const local = new LocalHlc('node-A', wall.read);
      // Remote is at physical 1000, logical 7 — same physical as ours
      const remote: HlcTimestamp = { physicalMs: 1_000, logical: 7, nodeId: 'node-B' };
      const merged = local.update(remote);
      expect(merged.physicalMs).toBe(1_000);
      expect(merged.logical).toBe(8); // max(0, 7) + 1
      expect(merged.nodeId).toBe('node-A');
    });

    it('adopts remote physical when remote is ahead', () => {
      const wall = fakeClock(1_000);
      const local = new LocalHlc('node-A', wall.read);
      const remote: HlcTimestamp = { physicalMs: 1_500, logical: 3, nodeId: 'node-B' };
      const merged = local.update(remote);
      expect(merged.physicalMs).toBe(1_500);
      expect(merged.logical).toBe(4); // remote.logical + 1
    });

    it('keeps local physical when remote is in the past', () => {
      const wall = fakeClock(2_000);
      const local = new LocalHlc('node-A', wall.read);
      const t0 = local.now();
      const remote: HlcTimestamp = { physicalMs: 500, logical: 99, nodeId: 'node-B' };
      const merged = local.update(remote);
      expect(merged.physicalMs).toBe(t0.physicalMs);
      // local's physical wins, logical bumps
      expect(merged.logical).toBeGreaterThan(t0.logical);
    });

    it('throws HlcSkewError when remote is too far in the future', () => {
      const wall = fakeClock(1_000);
      const local = new LocalHlc('node-A', wall.read, 5_000); // 5s skew tolerance
      const farFuture: HlcTimestamp = {
        physicalMs: 1_000 + 6_000, // 6s ahead
        logical: 0,
        nodeId: 'node-B',
      };
      expect(() => local.update(farFuture)).toThrow(HlcSkewError);
    });

    it('accepts remote within the skew window', () => {
      const wall = fakeClock(1_000);
      const local = new LocalHlc('node-A', wall.read, 5_000);
      const justInside: HlcTimestamp = {
        physicalMs: 1_000 + 4_999,
        logical: 0,
        nodeId: 'node-B',
      };
      expect(() => local.update(justInside)).not.toThrow();
    });

    it('default skew tolerance is 30s', () => {
      const wall = fakeClock(0);
      const local = new LocalHlc('node-A', wall.read);
      expect(local.maxSkewMs).toBe(DEFAULT_MAX_SKEW_MS);
      expect(DEFAULT_MAX_SKEW_MS).toBe(30_000);
    });
  });

  describe('compareHlc', () => {
    it('orders by physical first, then logical, then nodeId', () => {
      const aEarly: HlcTimestamp = { physicalMs: 1, logical: 0, nodeId: 'A' };
      const aLate: HlcTimestamp = { physicalMs: 2, logical: 0, nodeId: 'A' };
      const aLogical: HlcTimestamp = { physicalMs: 1, logical: 1, nodeId: 'A' };
      const bSame: HlcTimestamp = { physicalMs: 1, logical: 0, nodeId: 'B' };

      expect(compareHlc(aEarly, aLate)).toBe(-1);
      expect(compareHlc(aLate, aEarly)).toBe(1);
      expect(compareHlc(aEarly, aLogical)).toBe(-1);
      expect(compareHlc(aEarly, bSame)).toBe(-1); // A < B lex
      expect(compareHlc(bSame, aEarly)).toBe(1);
      expect(compareHlc(aEarly, aEarly)).toBe(0);
    });

    it('produces a total order on a randomized set', () => {
      const items: HlcTimestamp[] = [];
      for (let i = 0; i < 50; i++) {
        items.push({
          physicalMs: Math.floor(Math.random() * 100),
          logical: Math.floor(Math.random() * 10),
          nodeId: ['A', 'B', 'C', 'D'][Math.floor(Math.random() * 4)]!,
        });
      }
      const sorted = [...items].sort(compareHlc);
      for (let i = 1; i < sorted.length; i++) {
        expect(compareHlc(sorted[i - 1]!, sorted[i]!)).toBeLessThanOrEqual(0);
      }
    });
  });

  describe('helpers', () => {
    it('hlcToWallMs returns physicalMs', () => {
      expect(hlcToWallMs({ physicalMs: 42, logical: 99, nodeId: 'X' })).toBe(42);
    });

    it('wallMsToHlc lifts wall ms at logical=0', () => {
      const lifted = wallMsToHlc(42, 'X');
      expect(lifted).toEqual({ physicalMs: 42, logical: 0, nodeId: 'X' });
    });

    it('zeroHlc sorts before everything', () => {
      const z = zeroHlc('A');
      const real: HlcTimestamp = { physicalMs: 1, logical: 0, nodeId: 'A' };
      expect(compareHlc(z, real)).toBe(-1);
    });
  });

  describe('single-node degeneracy', () => {
    it('produces wall-clock-equivalent ordering when no updates ever arrive', () => {
      // ADR-101 promise: in single-node mode, HLC physicalMs tracks wall clock
      // and is pairwise-comparable to plain Unix timestamps.
      const wall = fakeClock(1_000);
      const hlc = new LocalHlc('solo', wall.read);

      const t0 = hlc.now();
      wall.advance(100);
      const t1 = hlc.now();
      wall.advance(50);
      const t2 = hlc.now();

      // Each timestamp should match wall when wall advanced
      expect(t0.physicalMs).toBe(1_000);
      expect(t1.physicalMs).toBe(1_100);
      expect(t2.physicalMs).toBe(1_150);
      // Logical stays at 0 because wall advanced each time
      expect(t0.logical).toBe(0);
      expect(t1.logical).toBe(0);
      expect(t2.logical).toBe(0);
      // → comparing physicalMs yields the same order as comparing HLCs
      expect(t0.physicalMs < t1.physicalMs).toBe(true);
      expect(t1.physicalMs < t2.physicalMs).toBe(true);
    });
  });
});

/**
 * V3 Claude-Flow Load Balancer Unit Tests
 *
 * London School TDD - Behavior Verification
 * Tests load calculation, rebalancing, preview, and imbalance detection
 *
 * @module v3/claims/tests/load-balancer
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { createMock, type MockedInterface } from '../../testing/src/helpers/create-mock.js';

// =============================================================================
// Domain Types
// =============================================================================

type AgentType = 'coder' | 'reviewer' | 'tester' | 'planner' | 'researcher' | 'queen-coordinator';
type AgentStatus = 'idle' | 'busy' | 'overloaded' | 'offline';

interface AgentLoad {
  agentId: string;
  agentType: AgentType;
  status: AgentStatus;
  currentClaims: number;
  maxClaims: number;
  utilizationPercent: number;
  queuedTasks: number;
  averageTaskDuration: number;
  lastActivityAt: Date;
}

interface ClaimSummary {
  issueId: string;
  agentId: string;
  priority: number;
  claimedAt: Date;
  estimatedDuration: number;
}

interface RebalanceAction {
  type: 'move' | 'reassign' | 'defer';
  claim: ClaimSummary;
  fromAgent: string;
  toAgent: string;
  reason: string;
}

interface RebalanceResult {
  success: boolean;
  actions: RebalanceAction[];
  movedClaims: number;
  error?: string;
}

interface RebalancePreview {
  proposedActions: RebalanceAction[];
  expectedImprovement: number;
  riskLevel: 'low' | 'medium' | 'high';
  warnings: string[];
}

interface ImbalanceReport {
  detected: boolean;
  severity: 'none' | 'minor' | 'moderate' | 'severe';
  overloadedAgents: string[];
  underloadedAgents: string[];
  imbalanceScore: number;
  recommendations: string[];
}

// =============================================================================
// Interfaces (Collaborators)
// =============================================================================

interface IAgentRegistry {
  getAgent(agentId: string): Promise<AgentInfo | null>;
  listAgents(filter?: AgentFilter): Promise<AgentInfo[]>;
  updateAgentStatus(agentId: string, status: AgentStatus): Promise<void>;
}

interface AgentInfo {
  id: string;
  type: AgentType;
  status: AgentStatus;
  maxClaims: number;
  capabilities: string[];
}

interface AgentFilter {
  type?: AgentType;
  status?: AgentStatus;
  available?: boolean;
}

interface IClaimRepository {
  findByAgent(agentId: string): Promise<ClaimSummary[]>;
  findAll(): Promise<ClaimSummary[]>;
  updateClaimAgent(issueId: string, newAgentId: string): Promise<void>;
}

interface ILoadCalculator {
  calculateUtilization(claims: number, maxClaims: number): number;
  calculateAverageTaskDuration(claims: ClaimSummary[]): number;
  determineStatus(utilization: number): AgentStatus;
}

interface IRebalanceStrategy {
  selectClaimsToMove(
    overloaded: AgentLoad,
    underloaded: AgentLoad[],
    claims: ClaimSummary[]
  ): RebalanceAction[];
  prioritizeActions(actions: RebalanceAction[]): RebalanceAction[];
  assessRisk(actions: RebalanceAction[]): 'low' | 'medium' | 'high';
}

interface IEventStore {
  append(event: LoadBalancerEvent): Promise<void>;
}

interface LoadBalancerEvent {
  type: string;
  timestamp: Date;
  payload: unknown;
}

// =============================================================================
// Configuration
// =============================================================================

interface LoadBalancerConfig {
  imbalanceThreshold: number; // Percentage difference that triggers rebalance
  maxActionsPerRebalance: number;
  minUtilizationForRebalance: number;
  cooldownPeriodMs: number;
  priorityWeights: {
    claimCount: number;
    utilization: number;
    queueDepth: number;
  };
}

const DEFAULT_CONFIG: LoadBalancerConfig = {
  imbalanceThreshold: 30, // 30% difference
  maxActionsPerRebalance: 10,
  minUtilizationForRebalance: 20,
  cooldownPeriodMs: 60000,
  priorityWeights: {
    claimCount: 0.4,
    utilization: 0.4,
    queueDepth: 0.2,
  },
};

// =============================================================================
// Service Under Test
// =============================================================================

class LoadBalancer {
  private lastRebalanceAt: Date | null = null;

  constructor(
    private readonly agentRegistry: IAgentRegistry,
    private readonly claimRepository: IClaimRepository,
    private readonly loadCalculator: ILoadCalculator,
    private readonly rebalanceStrategy: IRebalanceStrategy,
    private readonly eventStore: IEventStore,
    private readonly config: LoadBalancerConfig = DEFAULT_CONFIG
  ) {}

  async getAgentLoad(agentId: string): Promise<AgentLoad> {
    const agent = await this.agentRegistry.getAgent(agentId);
    if (!agent) {
      throw new Error(`Agent not found: ${agentId}`);
    }

    const claims = await this.claimRepository.findByAgent(agentId);
    const currentClaims = claims.length;
    const utilizationPercent = this.loadCalculator.calculateUtilization(
      currentClaims,
      agent.maxClaims
    );
    const status = this.loadCalculator.determineStatus(utilizationPercent);

    return {
      agentId,
      agentType: agent.type,
      status,
      currentClaims,
      maxClaims: agent.maxClaims,
      utilizationPercent,
      queuedTasks: 0, // Would be fetched from task queue
      averageTaskDuration: this.loadCalculator.calculateAverageTaskDuration(claims),
      lastActivityAt: claims.length > 0
        ? claims.reduce((latest, c) => c.claimedAt > latest ? c.claimedAt : latest, claims[0].claimedAt)
        : new Date(),
    };
  }

  async rebalance(): Promise<RebalanceResult> {
    // Check cooldown
    if (this.lastRebalanceAt) {
      const timeSinceLastRebalance = Date.now() - this.lastRebalanceAt.getTime();
      if (timeSinceLastRebalance < this.config.cooldownPeriodMs) {
        return {
          success: false,
          actions: [],
          movedClaims: 0,
          error: 'Rebalance on cooldown',
        };
      }
    }

    // Get all agents and their loads
    const agents = await this.agentRegistry.listAgents({ available: true });
    const agentLoads: AgentLoad[] = await Promise.all(
      agents.map((agent) => this.getAgentLoad(agent.id))
    );

    // Identify overloaded and underloaded agents
    const overloaded = agentLoads.filter((a) => a.status === 'overloaded');
    const underloaded = agentLoads.filter(
      (a) => a.status === 'idle' || a.utilizationPercent < this.config.minUtilizationForRebalance
    );

    if (overloaded.length === 0 || underloaded.length === 0) {
      this.lastRebalanceAt = new Date(); // Set cooldown even when nothing to rebalance
      return {
        success: true,
        actions: [],
        movedClaims: 0,
      };
    }

    // Generate rebalance actions
    const allActions: RebalanceAction[] = [];
    for (const overloadedAgent of overloaded) {
      const claims = await this.claimRepository.findByAgent(overloadedAgent.agentId);
      const actions = this.rebalanceStrategy.selectClaimsToMove(
        overloadedAgent,
        underloaded,
        claims
      );
      allActions.push(...actions);
    }

    // Prioritize and limit actions
    const prioritizedActions = this.rebalanceStrategy.prioritizeActions(allActions);
    const limitedActions = prioritizedActions.slice(0, this.config.maxActionsPerRebalance);

    // Execute actions
    let movedClaims = 0;
    for (const action of limitedActions) {
      if (action.type === 'move' || action.type === 'reassign') {
        await this.claimRepository.updateClaimAgent(action.claim.issueId, action.toAgent);
        movedClaims++;
      }
    }

    this.lastRebalanceAt = new Date();

    // Emit event
    await this.eventStore.append({
      type: 'LoadRebalanced',
      timestamp: new Date(),
      payload: {
        actions: limitedActions,
        movedClaims,
        overloadedCount: overloaded.length,
        underloadedCount: underloaded.length,
      },
    });

    return {
      success: true,
      actions: limitedActions,
      movedClaims,
    };
  }

  async previewRebalance(): Promise<RebalancePreview> {
    // Get all agents and their loads (read-only)
    const agents = await this.agentRegistry.listAgents({ available: true });
    const agentLoads: AgentLoad[] = await Promise.all(
      agents.map((agent) => this.getAgentLoad(agent.id))
    );

    // Identify overloaded and underloaded agents
    const overloaded = agentLoads.filter((a) => a.status === 'overloaded');
    const underloaded = agentLoads.filter(
      (a) => a.status === 'idle' || a.utilizationPercent < this.config.minUtilizationForRebalance
    );

    const warnings: string[] = [];
    if (overloaded.length === 0) {
      warnings.push('No overloaded agents detected');
    }
    if (underloaded.length === 0) {
      warnings.push('No underloaded agents available');
    }

    // Generate proposed actions without executing
    const proposedActions: RebalanceAction[] = [];
    for (const overloadedAgent of overloaded) {
      const claims = await this.claimRepository.findByAgent(overloadedAgent.agentId);
      const actions = this.rebalanceStrategy.selectClaimsToMove(
        overloadedAgent,
        underloaded,
        claims
      );
      proposedActions.push(...actions);
    }

    const prioritizedActions = this.rebalanceStrategy.prioritizeActions(proposedActions);
    const limitedActions = prioritizedActions.slice(0, this.config.maxActionsPerRebalance);

    // Calculate expected improvement
    const currentImbalance = this.calculateImbalanceScore(agentLoads);
    const expectedImprovement = Math.min(limitedActions.length * 5, 50); // Simplified calculation

    // Assess risk
    const riskLevel = this.rebalanceStrategy.assessRisk(limitedActions);

    return {
      proposedActions: limitedActions,
      expectedImprovement,
      riskLevel,
      warnings,
    };
  }

  async detectImbalance(): Promise<ImbalanceReport> {
    const agents = await this.agentRegistry.listAgents({ available: true });
    const agentLoads: AgentLoad[] = await Promise.all(
      agents.map((agent) => this.getAgentLoad(agent.id))
    );

    const overloaded = agentLoads.filter((a) => a.status === 'overloaded');
    const underloaded = agentLoads.filter(
      (a) => a.status === 'idle' || a.utilizationPercent < this.config.minUtilizationForRebalance
    );

    const imbalanceScore = this.calculateImbalanceScore(agentLoads);
    const detected = imbalanceScore > this.config.imbalanceThreshold;

    let severity: 'none' | 'minor' | 'moderate' | 'severe' = 'none';
    if (imbalanceScore > 60) {
      severity = 'severe';
    } else if (imbalanceScore > 40) {
      severity = 'moderate';
    } else if (imbalanceScore > this.config.imbalanceThreshold) {
      severity = 'minor';
    }

    const recommendations: string[] = [];
    if (detected) {
      if (overloaded.length > 0) {
        recommendations.push(`${overloaded.length} agent(s) are overloaded and need relief`);
      }
      if (underloaded.length > 0) {
        recommendations.push(`${underloaded.length} agent(s) have capacity available`);
      }
      if (severity === 'severe') {
        recommendations.push('Immediate rebalancing recommended');
      }
    }

    // Emit event if imbalance detected
    if (detected) {
      await this.eventStore.append({
        type: 'ImbalanceDetected',
        timestamp: new Date(),
        payload: {
          severity,
          imbalanceScore,
          overloadedAgents: overloaded.map((a) => a.agentId),
          underloadedAgents: underloaded.map((a) => a.agentId),
        },
      });
    }

    return {
      detected,
      severity,
      overloadedAgents: overloaded.map((a) => a.agentId),
      underloadedAgents: underloaded.map((a) => a.agentId),
      imbalanceScore,
      recommendations,
    };
  }

  private calculateImbalanceScore(loads: AgentLoad[]): number {
    if (loads.length === 0) return 0;

    const utilizations = loads.map((l) => l.utilizationPercent);
    const maxUtilization = Math.max(...utilizations);
    const minUtilization = Math.min(...utilizations);
    const avgUtilization = utilizations.reduce((a, b) => a + b, 0) / utilizations.length;

    // Calculate standard deviation
    const variance =
      utilizations.reduce((sum, u) => sum + Math.pow(u - avgUtilization, 2), 0) / utilizations.length;
    const stdDev = Math.sqrt(variance);

    // Score based on range and standard deviation
    const rangeScore = maxUtilization - minUtilization;
    const deviationScore = stdDev * 2;

    return Math.min(100, rangeScore * 0.6 + deviationScore * 0.4);
  }

  // For testing - reset cooldown
  resetCooldown(): void {
    this.lastRebalanceAt = null;
  }
}

