      expect(result.success).toBe(true);
      expect(mockStealingPolicy.canSteal).toHaveBeenCalledWith(
        queenClaimant,
        coderClaimant,
        coderClaim
      );
    });

    it('should verify stealing policy is called with correct arguments', async () => {
      // Given
      const claim: Claim = {
        issueId: 'issue-1',
        claimant: coderClaimant,
        status: 'active',
        claimedAt: pastDate,
        expiresAt: futureDate,
